<?php
$pageTitle='Find Vendors Near You';$theme='burgundy';require_once 'includes/db.php';$area=(int)($_GET['area']??0);$cat=trim($_GET['category']??'');$sql='SELECT v.*,a.name area FROM vendors v LEFT JOIN areas a ON a.id=v.area_id WHERE v.active=1';$params=[];if($area){$sql.=' AND v.area_id=?';$params[]=$area;}if($cat!==''){$sql.=' AND v.category=?';$params[]=$cat;}$sql.=' ORDER BY v.verified DESC,v.rating DESC';$q=$pdo->prepare($sql);$q->execute($params);$vendors=$q->fetchAll();$areas=$pdo->query('SELECT * FROM areas WHERE active=1 ORDER BY name')->fetchAll();$cats=$pdo->query("SELECT DISTINCT category FROM vendors ORDER BY category")->fetchAll();include 'includes/header.php';
?>
<section class="py-5"><div class="container"><div class="section-title"><p class="eyebrow" style="color:var(--burgundy)">LOCAL VENDOR FINDER</p><h2>Find trusted celebration services in Quetta</h2></div><form class="content-card p-3 mb-4"><div class="row g-2"><div class="col-md-5"><select name="area" class="form-select"><option value="0">All Quetta areas</option><?php foreach($areas as $a):?><option value="<?=$a['id']?>" <?=$area==$a['id']?'selected':''?>><?=htmlspecialchars($a['name'])?></option><?php endforeach;?></select></div><div class="col-md-5"><select name="category" class="form-select"><option value="">All categories</option><?php foreach($cats as $c):?><option <?=$cat===$c['category']?'selected':''?>><?=htmlspecialchars($c['category'])?></option><?php endforeach;?></select></div><div class="col-md-2 d-grid"><button class="btn btn-brand" style="background:var(--burgundy)">Search</button></div></div></form><div class="row g-4"><?php foreach($vendors as $v):?><div class="col-md-6 col-lg-4"><article class="content-card h-100 p-3"><img src="<?=htmlspecialchars($v['image'])?>" class="w-100 rounded-4" style="height:220px;object-fit:cover" alt=""><div class="p-3"><div class="d-flex justify-content-between"><span class="badge text-bg-light"><?=htmlspecialchars($v['category'])?></span><?php if($v['verified']):?><span class="badge bg-success"><i class="bi bi-patch-check-fill"></i> Verified</span><?php endif;?></div><h4 class="mt-3"><?=htmlspecialchars($v['name'])?></h4><p class="small text-muted"><i class="bi bi-geo-alt"></i> <?=htmlspecialchars($v['area']??'Quetta')?> · ⭐ <?=number_format($v['rating'],1)?></p><p class="text-muted"><?=htmlspecialchars($v['description'])?></p><div class="d-flex gap-2"><a href="vendor-profile.php?id=<?=$v['id']?>" class="btn btn-outline-dark">View Profile</a><a href="booking.php?vendor_id=<?=$v['id']?>" class="btn btn-brand" style="background:var(--burgundy)">Book</a></div></div></article></div><?php endforeach;?></div><?php if(!$vendors):?><div class="alert alert-info mt-4">No vendors match your filters.</div><?php endif;?></div></section>
